  function updateHud(){if(!$(`humanHealth`))return;$(`humanHealth`).textContent=`♥ ${state.human.hp}/5`;$(`humanShield`).textContent=`◆ ${state.human.shield}/5`;$(`shipHealth`).textContent=`♥ ${state.ship.hp}/20`;$(`shipShield`).textContent=`◆ ${state.ship.shield}/20`}
  function showAdventure(){document.querySelectorAll("dialog[open]").forEach(dialog=>{if(typeof dialog.close==="function")dialog.close();else dialog.removeAttribute("open")});["raceFeedback","imageLightbox"].forEach(id=>{const layer=$(id);if(layer)layer.hidden=true});ROOT.hidden=false;document.body.classList.add("adventure-active");$("adventureHud").hidden=state.screen==="landing";render()}
  function showLegacy(target="practice"){ROOT.hidden=true;document.body.classList.remove("adventure-active");location.hash=target;$("adventureMenu").hidden=true}
