  function closeMenu(){$("adventureMenu").hidden=true;$(`adventureMenuButton`).setAttribute("aria-expanded","false")}
  function journeyScene(){if(["cockpit","pilotSelect"].includes(state.screen))return"cockpit";if(state.screen==="garden")return"garden";if(state.screen==="map")return"map";if(["earthHub","storage","science"].includes(state.screen))return"earth";if(state.screen==="shipLaunch")return"launch";if(["bossIntro","boss","reward"].includes(state.screen))return"boss";const kind=state.screen==="brief"?state.brief:state.mission?.kind;return({earthParts:"earth",earthReady:"earth",moonTravel:"moon-travel",moonPrep:"moon-base",marsTravel:"mars-travel",marsSurvey:"mars"})[kind]||"default"}
  function openEarth(){state.screen="earthHub";save();VIEW.scrollTop=0;render()}
  function openCockpit(){state.screen="cockpit";save();VIEW.scrollTop=0;render()}
  function renderScience(){if(!window.ScienceDiscovery)return notify("Science Discovery is still loading.");window.ScienceDiscovery.render({state,view:VIEW,save,updateHud,openEarth:openCockpit,renderAdventure:render})}
  function vaultQuestion(excluded=[]){const pool=questionPool().filter(q=>!q.image&&!excluded.includes(q._id)&&String(q.en||"").length<420),q=pool[Math.floor(Math.random()*pool.length)];return q?{id:q._id,prompt:formattedQuestion(q.en),skill:q.skill||"Maths",paper:q._paper||"Practice"}:null}
  function renderStorageV2(){if(!window.TreasureVault)return renderStorage();window.TreasureVault.mount({root:VIEW,state,save,onExit:openCockpit,getQuestion:vaultQuestion,checkAnswer:(id,value)=>{const q=getQuestion(id);return!!q&&accepted(q,value)},onPilotSwap:()=>{state.pilot=state.pilot==="seal"?"penguin":"seal";save();return pilotInfo(state.pilot).name}})}
  function finalizeCockpitNavigation(){["scienceEarthBack","journalBack","storageBack"].forEach(id=>{const button=$(id);if(button){button.textContent="← Cockpit";button.onclick=openCockpit}});const pilotButton=$("cockpitPilotInfo");if(pilotButton){pilotButton.textContent="Change pilot · 1 Knowledge Gem";pilotButton.onclick=()=>{state.gemWorkshop.focus="pilot";state.screen="storage";save();render()}}}
  function refreshScienceCounts(){if(state.screen!=="earthHub")return;const days=Object.values(state.science.completedByWeek||{}).reduce((sum,list)=>sum+(Array.isArray(list)?list.length:0),0),research=document.querySelector(".earth-path-card.research"),journal=document.querySelector(".earth-path-card.vocabulary");if(research){const description=research.querySelector("p:not(.adventure-kicker)"),stats=research.querySelectorAll(".path-meta b");if(description)description.textContent=`Choose among ${SCIENCE_WEEK_COUNT} complete science weeks and follow each story at your own pace.`;if(stats[0])stats[0].textContent=`${days}/${SCIENCE_TOTAL_DAYS} science days`}if(journal){const stats=journal.querySelectorAll(".path-meta b");if(stats[0])stats[0].textContent=`${SCIENCE_WEEK_COUNT} weekly collections`}}
  function render(){applyRegen();clearTimeout(introTimer);clearTimeout(gardenTimer);if(state.screen!=="science"){if(window.ScienceMaze)window.ScienceMaze.destroy();if(window.ScienceArcade)window.ScienceArcade.destroy()}if(state.screen!=="storage"&&window.TreasureVault)window.TreasureVault.destroy();ROOT.dataset.scene=journeyScene();$("adventureHud").hidden=["landing","pilotSelect"].includes(state.screen);if(state.screen==="landing")renderLanding();else if(state.screen==="pilotSelect")renderPilotSelect();else if(state.screen==="cockpit")renderCockpit();else if(state.screen==="garden")renderGarden();else if(state.screen==="map")renderMap();else if(state.screen==="earthHub")renderEarthHub();else if(state.screen==="storage")renderStorageV2();else if(state.screen==="science")renderScience();else if(state.screen==="brief")renderBrief();else if(state.screen==="shipyard")renderShipyard();else if(state.screen==="shipLaunch")renderShipLaunch();else if(state.screen==="mission")renderMission();else if(state.screen==="bossIntro")renderBossIntro();else if(state.screen==="boss")renderBoss();else if(state.screen==="reward")renderReward();refreshScienceCounts();finalizeCockpitNavigation();updateHud()}
  function renderLanding(){const continuing=state.started;VIEW.innerHTML=`<section class="adventure-landing"><div class="landing-orbits" aria-hidden="true"><i></i><i></i><i></i></div><div class="landing-copy"><p class="adventure-kicker">INTERNATIONAL MATH · SOLAR QUEST</p><h1>START FROM <span>EARTH</span></h1><p>Build your spaceship, solve maths missions and rescue friends across the Solar System.</p><button class="start-adventure-button" id="startAdventure" type="button">${continuing?"Enter your cockpit":"Choose your pilot"} →</button>${continuing?`<small class="continue-note">All saved progress is ready · Current location: ${esc(state.location)}</small>`:""}</div></section>`;$("startAdventure").onclick=()=>{state.started=true;state.screen=continuing?"cockpit":"pilotSelect";save();render()}}
  function pilotInfo(id){return id==="seal"?{name:"Mochi",role:"Curious ocean scientist",image:"assets/pilot-seal-v1.png"}:{name:"Pico",role:"Brave space explorer",image:"assets/pilot-penguin-v1.png"}}
  function renderPilotSelect(){VIEW.scrollTop=0;VIEW.innerHTML=`<section class="pilot-select-screen"><div class="pilot-select-heading"><p class="adventure-kicker">WELCOME ABOARD · STEP 1</p><h1>Choose your pilot</h1><p>Both explorers have the same abilities. Choose the friend you would like to see inside your cockpit.</p></div><div class="pilot-choice-grid"><article class="pilot-choice-card"><img src="assets/pilot-penguin-v1.png" alt="Pico the chibi penguin space explorer"><div><p class="adventure-kicker">PENGUIN EXPLORER</p><h2>Pico</h2><p>Brave, cheerful and ready to investigate every clue.</p><button data-pilot="penguin">Choose Pico →</button></div></article><article class="pilot-choice-card"><img src="assets/pilot-seal-v1.png" alt="Mochi the chibi seal space scientist"><div><p class="adventure-kicker">SEAL SCIENTIST</p><h2>Mochi</h2><p>Curious, playful and always excited by a new discovery.</p><button data-pilot="seal">Choose Mochi →</button></div></article></div></section>`;document.querySelectorAll("[data-pilot]").forEach(button=>button.onclick=()=>{state.pilot=button.dataset.pilot;state.screen="cockpit";save();render()})}
  function renderCockpit(){const pilot=pilotInfo(state.pilot),byWeek=state.science.completedByWeek||{1:state.science.completedDays||[],2:[],3:[],4:[],5:[],6:[]},scienceDays=Object.values(byWeek).reduce((sum,list)=>sum+(Array.isArray(list)?list.length:0),0),remembered=(state.science.vocabularyNotes||[]).length,growing=state.garden.pots.filter(Boolean).length;VIEW.scrollTop=0;VIEW.innerHTML=`<section class="cockpit-home-screen"><img class="cockpit-home-bg" src="assets/cockpit-home-v1.png" alt="Bright spaceship cockpit looking toward Earth"><div class="cockpit-vignette" aria-hidden="true"></div><header class="cockpit-welcome"><p class="adventure-kicker">EARTH ORBIT · YOUR HOME SHIP</p><h1>Where will we explore today?</h1><p>${pilot.name} is ready. Choose one route or open an object in the room.</p></header><div class="cockpit-route-grid"><button class="cockpit-route-card research-route" id="cockpitResearch"><small>EARTH RESEARCH</small><strong>Observe. Explain.<br>Discover.</strong><span>${scienceDays}/${SCIENCE_TOTAL_DAYS} science days · ${SCIENCE_WEEK_COUNT} weeks</span><b>Open research →</b></button><button class="cockpit-route-card rescue-route" id="cockpitRescue"><small>RESCUE FRIENDS</small><strong>Build. Travel.<br>Rescue.</strong><span>${state.shipParts}/10 ship parts · ${state.mascots.length} friends safe</span><b>Open star map →</b></button></div><div class="cockpit-pilot"><img src="${pilot.image}" alt="${pilot.name}, your selected animal pilot"><div><strong>${pilot.name}</strong><span>${pilot.role}</span><button id="cockpitPilotInfo">Change pilot · Gem system next</button></div></div><nav class="cockpit-hotspots" aria-label="Cockpit rooms and objects"><button class="cockpit-hotspot chest" id="cockpitStorage"><span>Storage chest</span><small>${collectionCount()} collected objects</small></button><button class="cockpit-hotspot journal" id="cockpitJournal"><span>Vocabulary journal</span><small>${remembered} words marked</small></button><button class="cockpit-hotspot lab locked" data-locked-room="Science Lab"><span>Science Lab</span><small>Unlocks in the next phase</small></button><button class="cockpit-hotspot garden" id="cockpitGarden"><span>Garden</span><small>${growing}/3 pots active · ${state.garden.harvests} harvested</small></button><button class="cockpit-hotspot living locked" data-locked-room="Living Room"><span>Living Room</span><small>Aquarium planned</small></button><button class="cockpit-hotspot engine locked" data-locked-room="Engine Room"><span>Engine Room</span><small>Coming later</small></button><button class="cockpit-hotspot outside locked" data-locked-room="Outside"><span>Outside</span><small>Coming later</small></button></nav><p class="cockpit-flow-note">One click starts a mission. Existing progress stays exactly where you left it.</p></section>`;$("cockpitResearch").onclick=()=>{state.screen="science";state.science.view="lab";save();render()};$("cockpitRescue").onclick=()=>{state.screen="map";save();render()};$("cockpitStorage").onclick=()=>{state.screen="storage";save();render()};$("cockpitJournal").onclick=()=>{state.screen="science";state.science.view="journal";save();render()};$("cockpitGarden").onclick=()=>{state.screen="garden";save();render()};$("cockpitPilotInfo").onclick=()=>notify("Pilot switching will cost one complete Knowledge Gem after the Gem Workshop is activated.");document.querySelectorAll("[data-locked-room]").forEach(button=>button.onclick=()=>notify(`${button.dataset.lockedRoom} is visible now and will become playable in the next development phase.`))}
  const GARDEN_WAIT_HOURS=[24,24,48,24,48,24,24],GARDEN_PLANTS={
    tomato:{name:"Tomato",icon:"🍅",atlas:"tomato-growth-atlas-v1.png",aspect:.9,imageHeight:"240%",rowShift:"-103%",stages:["Seed","Sprout","Shoot","Seedling","Climbing vine","Flowering","Fruiting"],facts:["A tomato seed rests in moist soil.","Seed leaves open above the soil.","The first true leaves begin to grow.","The flexible stem needs support as it lengthens.","The stem is trained upward on a stake.","Yellow flowers form before any fruit.","Ripe tomatoes contain seeds for the next crop."],harvest:"tomatoes",sample:"Orbital Garden tomato sample",seedYield:1},
    pea:{name:"Pea",icon:"🫛",atlas:"pea-growth-atlas-v1.png",aspect:.6,imageHeight:"240%",rowShift:"-103%",stages:["Seed","Sprout","Shoot","Tendrils","Climbing vine","Flowering","Pods"],facts:["A pea stores food inside its large seed.","The root and shoot emerge during germination.","Compound leaves begin to unfold.","Curling tendrils search for a support.","Tendrils hold the soft vine on the trellis.","White flowers form before the pods.","Each green pod protects several pea seeds."],harvest:"pea pods",sample:"Orbital Garden pea pod sample",seedYield:2},
    sunflower:{name:"Sunflower",icon:"🌻",atlas:"sunflower-growth-atlas-v1.png",aspect:.6,imageHeight:"240%",rowShift:"-109%",stages:["Seed","Sprout","Shoot","Seedling","Tall stem","Flowering","Seed head"],facts:["A striped sunflower seed lies in the soil.","Two seed leaves rise toward the light.","The upright stem begins to strengthen.","Broad true leaves collect sunlight.","A tall herbaceous stem supports the bud.","Many tiny flowers make one flower head.","The mature disk holds many sunflower seeds."],harvest:"sunflower seeds",sample:"Orbital Garden sunflower seed sample",seedYield:2},
    carrot:{name:"Carrot",icon:"🥕",atlas:"carrot-growth-atlas-v1.png",aspect:.6,imageHeight:"240%",rowShift:"-120%",stages:["Seed","Sprout","First leaves","Leaf rosette","Root thickening","Mature foliage","Taproot"],facts:["Tiny carrot seeds begin in loose soil.","A delicate shoot appears above ground.","Feathery true leaves begin to form.","A leaf rosette gathers energy from light.","The taproot thickens below the soil.","Dense leaves feed the hidden storage root.","The edible orange carrot is a swollen taproot."],harvest:"carrot root",sample:"Orbital Garden carrot root sample",seedYield:0}
  };
  function gardenSeedTotal(){return Object.values(state.garden.seeds).reduce((sum,value)=>sum+(Number(value)||0),0)}
  function gardenRemaining(milliseconds){if(milliseconds<=0)return"Ready now";const minutes=Math.ceil(milliseconds/60000),days=Math.floor(minutes/1440),hours=Math.floor(minutes%1440/60),mins=minutes%60;if(days)return`${days}d ${hours}h remaining`;if(hours)return`${hours}h ${mins}m remaining`;return`${mins}m remaining`}
  function gardenSprite(kind,frame){const plant=GARDEN_PLANTS[kind]||GARDEN_PLANTS.tomato,col=frame%4,row=Math.floor(frame/4),top=row?plant.rowShift:"0%";return`<span class="garden-sprite" style="--garden-col:${col};--garden-aspect:${plant.aspect};--garden-image-height:${plant.imageHeight};--garden-top:${top}" aria-hidden="true"><img src="assets/${plant.atlas}?v=20261004" alt=""></span>`}
  function gardenSeedButtons(index){return`<div class="garden-seed-options">${Object.entries(GARDEN_PLANTS).map(([kind,plant])=>{const count=state.garden.seeds[kind]||0,disabled=!state.garden.starterClaimed||state.garden.soil<1||state.garden.water<1||count<1;return`<button data-garden-plant="${index}" data-kind="${kind}" ${disabled?"disabled":""}><b>${plant.icon} ${plant.name}</b><small>${count} seed${count===1?"":"s"}</small></button>`}).join("")}</div>`}
  function gardenPotMarkup(pot,index){if(!pot)return`<article class="garden-pot-card empty">${gardenSprite("tomato",0)}<div><p class="garden-pot-number">POT ${index+1}</p><h2>Choose a seed</h2><p>Every species grows differently. Planting uses one soil pack and one water unit.</p>${gardenSeedButtons(index)}</div></article>`;const plant=GARDEN_PLANTS[pot.kind]||GARDEN_PLANTS.tomato,now=Date.now(),ready=now>=pot.readyAt,final=pot.stage>=plant.stages.length-1,frame=Math.min(7,pot.stage+1);return`<article class="garden-pot-card ${ready?"ready":"waiting"}">${gardenSprite(pot.kind,frame)}<div><p class="garden-pot-number">POT ${index+1} · ${plant.name.toUpperCase()} · STAGE ${pot.stage+1}/7</p><h2>${plant.icon} ${plant.stages[pot.stage]}</h2><p>${plant.facts[pot.stage]}</p><span class="garden-time ${ready?"is-ready":""}">${gardenRemaining(pot.readyAt-now)}</span>${ready?`<button data-garden-${final?"harvest":"grow"}="${index}">${final?`Harvest ${plant.harvest}`:"Water & grow"}</button>`:""}</div></article>`}
  function renderGarden(){const pilot=pilotInfo(state.pilot),pots=state.garden.pots.map(gardenPotMarkup).join("");VIEW.scrollTop=0;VIEW.innerHTML=`<section class="garden-screen"><img class="garden-room-bg" src="assets/garden-room-v1.png" alt="Bright spaceship greenhouse with Earth outside"><div class="garden-room-shade" aria-hidden="true"></div><header class="garden-heading"><button id="gardenBack">← Cockpit</button><div><p class="adventure-kicker">ORBITAL GARDEN · BIOLOGY</p><h1>Grow living specimens</h1><p>Compare four real plant life cycles through observation and care.</p></div></header><aside class="garden-resource-panel"><strong>GARDEN SUPPLIES</strong><span>🟫 Soil <b>${state.garden.soil}</b></span><span>💧 Water <b>${state.garden.water}</b></span><span>🌱 Seeds <b>${gardenSeedTotal()}</b></span><span>🧺 Harvests <b>${state.garden.harvests}</b></span>${state.garden.starterClaimed?(state.garden.catalogVersion<1?`<button id="gardenCatalog">Collect 3 new seed samples</button>`:""):`<button id="gardenStarter">Open starter kit</button>`}</aside><div class="garden-guide"><img src="${pilot.image}" alt="${pilot.name}"><p><strong>${pilot.name} says:</strong> Compare how tendrils, stems and roots grow. Plants never die here; an unfinished stage pauses safely until you return.</p></div><div class="garden-pot-grid">${pots}</div></section>`;$("gardenBack").onclick=openCockpit;if($("gardenStarter"))$("gardenStarter").onclick=claimGardenStarter;if($("gardenCatalog"))$("gardenCatalog").onclick=claimGardenCatalog;document.querySelectorAll("[data-garden-plant]").forEach(button=>button.onclick=()=>plantGardenPot(Number(button.dataset.gardenPlant),button.dataset.kind));document.querySelectorAll("[data-garden-grow]").forEach(button=>button.onclick=()=>growGardenPot(Number(button.dataset.gardenGrow)));document.querySelectorAll("[data-garden-harvest]").forEach(button=>button.onclick=()=>harvestGardenPot(Number(button.dataset.gardenHarvest)));gardenTimer=setTimeout(()=>{if(state.screen==="garden")renderGarden()},60000)}
  function claimGardenStarter(){if(state.garden.starterClaimed)return;state.garden.starterClaimed=true;state.garden.catalogVersion=1;state.garden.soil+=3;state.garden.water+=21;state.garden.seeds.tomato+=2;state.garden.seeds.pea++;state.garden.seeds.sunflower++;state.garden.seeds.carrot++;save();renderGarden()}
  function claimGardenCatalog(){if(!state.garden.starterClaimed||state.garden.catalogVersion>=1)return;state.garden.catalogVersion=1;state.garden.seeds.pea++;state.garden.seeds.sunflower++;state.garden.seeds.carrot++;save();renderGarden()}
  function plantGardenPot(index,kind){const plant=GARDEN_PLANTS[kind];if(!plant||state.garden.pots[index]||state.garden.soil<1||state.garden.water<1||(state.garden.seeds[kind]||0)<1)return notify("This planter needs the selected seed, one soil pack and water.");state.garden.soil--;state.garden.water--;state.garden.seeds[kind]--;state.garden.pots[index]={kind,stage:0,readyAt:Date.now()+GARDEN_WAIT_HOURS[0]*3600000,plantedAt:Date.now()};save();renderGarden()}
  function growGardenPot(index){const pot=state.garden.pots[index],plant=pot&&GARDEN_PLANTS[pot.kind];if(!pot||!plant||Date.now()<pot.readyAt)return;if(state.garden.water<1)return notify("You need one water unit. Future Geography missions will help you find more.");state.garden.water--;pot.stage=Math.min(plant.stages.length-1,pot.stage+1);pot.readyAt=Date.now()+GARDEN_WAIT_HOURS[pot.stage]*3600000;save();renderGarden()}
