  function setupMapControls(){const canvas=$("solarCanvas"),viewport=$("solarViewport");const draw=()=>canvas.style.transform=`translate(${mapX}px,${mapY}px) scale(${mapScale})`;$("zoomInMap").onclick=()=>{mapScale=Math.min(2.2,mapScale+.2);draw()};$("zoomOutMap").onclick=()=>{mapScale=Math.max(.75,mapScale-.2);draw()};$("resetMap").onclick=()=>{mapScale=1;mapX=mapY=0;draw()};viewport.onpointerdown=e=>{if(e.target.closest("button"))return;dragStart={x:e.clientX-mapX,y:e.clientY-mapY};viewport.setPointerCapture(e.pointerId)};viewport.onpointermove=e=>{if(!dragStart)return;mapX=e.clientX-dragStart.x;mapY=e.clientY-dragStart.y;draw()};viewport.onpointerup=()=>dragStart=null}
  function selectPlace(place){const futureWorlds={mercury:"Mercury",venus:"Venus",jupiter:"Jupiter",saturn:"Saturn",uranus:"Uranus",neptune:"Neptune",wormhole:"Other worlds"};if(futureWorlds[place])return notify(`${futureWorlds[place]} is visible on your chart and will open in a future mission.`);if(place==="earth")return openEarth();if(!state.shipBuilt)return notify("Build your spaceship on Earth first.");if(state.ship.brokenUntil>Date.now())return notify("The spaceship is being repaired. Try again when the repair timer ends.");if(place==="moon")return setBrief(state.missions.moonTravel?state.missions.moonPrep?state.missions.moonBoss?"moonComplete":"moonBoss":"moonPrep":"moonTravel");if(place==="mars")return setBrief(state.missions.marsTravel?state.missions.marsSurvey?"marsComplete":"marsSurvey":"marsTravel");if(place==="comet")return setBrief("comet");if(place==="ore")return setBrief("ore")}
