  function startMission(kind,total){const travel=/Travel|comet/.test(kind),done=kind==="earthParts"?Math.min(state.shipParts,total):0;state.mission={kind,total,done,currentId:"",travel,notice:""};if(travel&&Math.random()<.5){const loss=Math.floor(Math.random()*5)+1;state.ship.shield=Math.max(0,state.ship.shield-loss);state.mission.notice=`Meteor storm! The ship lost ${loss} Shield.`}state.screen="mission";save();nextMissionQuestion()}
