  function detectFigureCrop(source){const scan=document.createElement("canvas"),context=scan.getContext("2d",{willReadFrequently:true});scan.width=source.naturalWidth;scan.height=source.naturalHeight;context.drawImage(source,0,0);const pixels=context.getImageData(0,0,scan.width,scan.height).data;let left=scan.width,top=scan.height,right=-1,bottom=-1;for(let y=0;y<scan.height;y+=2)for(let x=0;x<scan.width;x+=2){const i=(y*scan.width+x)*4,r=pixels[i],g=pixels[i+1],b=pixels[i+2],average=(r+g+b)/3,spread=Math.max(r,g,b)-Math.min(r,g,b);if(average<210&&(spread<35||average<105)){left=Math.min(left,x);right=Math.max(right,x);top=Math.min(top,y);bottom=Math.max(bottom,y)}}if(right<left||bottom<top)return[0,0,scan.width,scan.height];const padding=14;left=Math.max(0,left-padding);top=Math.max(0,top-padding);right=Math.min(scan.width-1,right+padding);bottom=Math.min(scan.height-1,bottom+padding);return[left,top,right-left+1,bottom-top+1]}
  function cleanTimoWatermark(context,w,h){const image=context.getImageData(0,0,w,h),pixels=image.data;for(let i=0;i<pixels.length;i+=4){const r=pixels[i],g=pixels[i+1],b=pixels[i+2],average=(r+g+b)/3,spread=Math.max(r,g,b)-Math.min(r,g,b);if(average>145&&spread>42){pixels[i]=pixels[i+1]=pixels[i+2]=255}}context.putImageData(image,0,0)}
  function prepareQuestionImage(q){const image=$("missionQuestionImage"),zoom=$("missionZoom");if(!image||!q.image)return;const finish=src=>{image.src=src;image.style.opacity="1";const open=()=>openAdventureImage(src,image.alt);image.onclick=open;zoom.onclick=open;image.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();open()}};image.tabIndex=0};if(typeof window.prepareQuestionImageElement==="function")return window.prepareQuestionImageElement(q,image,finish);const assetSrc=`${q.image}${q.image.includes("?")?"&":"?"}v=20260926-2`;const autoTrim=/assets\/timo\//.test(q.image);if(!q.crop&&!autoTrim)return finish(assetSrc);image.style.opacity="0";const source=new Image();source.onload=()=>{const [x,y,w,h]=q.crop||detectFigureCrop(source),canvas=document.createElement("canvas"),context=canvas.getContext("2d");canvas.width=w;canvas.height=h;context.fillStyle="#fff";context.fillRect(0,0,w,h);context.drawImage(source,x,y,w,h,0,0,w,h);if(autoTrim)cleanTimoWatermark(context,w,h);finish(canvas.toDataURL("image/png"))};source.onerror=()=>finish(assetSrc);source.src=assetSrc}
